function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqlJson(value) {
  return `${sql(JSON.stringify(value ?? {}))}::jsonb`;
}

function slug(value, fallback = '') {
  return String(value || fallback || '').trim();
}

const crypto = require('crypto');

const body = $json.body || {};

const draftId = crypto.randomUUID();

const generatedAssetId = String(
  body.generatedAssetId ||
  body.generated_asset_id ||
  ''
).trim();

const assetId = String(
  body.assetId ||
  body.asset_id ||
  ''
).trim();

const avatar = slug(body.avatar);
const scene = slug(body.scene);
const assetType = slug(body.assetType || body.asset_type, 'raw-image');
const platform = slug(body.platform, 'instagram');

const caption = String(
  body.caption ||
  body.captionIdea ||
  'Una pausa en movimiento, una historia que apenas empieza.'
).trim();

const hashtags = Array.isArray(body.hashtags)
  ? body.hashtags
  : ['estefania', 'lifestyle', 'travel', 'airport', 'cinematic'];

const baseUrl = slug(
  body.baseUrl || body.base_url,
  'http://192.168.0.194:9000'
).replace(/\/$/, '');

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const slugRegex = /^[a-z0-9][a-z0-9-]*$/i;

let src;

if (uuidRegex.test(generatedAssetId)) {
  src = `
chosen AS (
  SELECT
    car.asset_id,
    car.avatar,
    car.scene,
    car.asset_type,
    car.bucket,
    car.object_path,
    car.mime_type,
    car.metadata,
    ga.generated_asset_id
  FROM generated_assets ga
  JOIN canonical_asset_registry car
    ON car.asset_id = ga.asset_id::text
  WHERE ga.generated_asset_id = ${sql(generatedAssetId)}::uuid
    AND ga.status = 'approved'
  LIMIT 1
)`;
} else if (uuidRegex.test(assetId)) {
  src = `
chosen AS (
  SELECT
    car.asset_id,
    car.avatar,
    car.scene,
    car.asset_type,
    car.bucket,
    car.object_path,
    car.mime_type,
    car.metadata,
    NULL::uuid AS generated_asset_id
  FROM canonical_asset_registry car
  WHERE car.asset_id = ${sql(assetId)}
  LIMIT 1
)`;
} else {
  if (
    !slugRegex.test(avatar) ||
    !slugRegex.test(scene) ||
    !slugRegex.test(assetType)
  ) {
    return {
      json: {
        ok: false,
        skipQuery: true,
        error: 'generatedAssetId, assetId, or avatar/scene/assetType are required',
        request: {
          generatedAssetId,
          assetId,
          avatar,
          scene,
          assetType,
          platform
        }
      }
    };
  }

  src = `
chosen AS (
  SELECT
    car.asset_id,
    car.avatar,
    car.scene,
    car.asset_type,
    car.bucket,
    car.object_path,
    car.mime_type,
    car.metadata,
    NULL::uuid AS generated_asset_id
  FROM canonical_asset_registry car
  WHERE car.avatar = ${sql(avatar)}
    AND car.scene = ${sql(scene)}
    AND car.asset_type = ${sql(assetType)}
    AND (
      COALESCE(car.is_canonical, false) = true
      OR car.status = 'canonical'
    )
  ORDER BY car.created_at DESC
  LIMIT 1
)`;
}

const query = `
WITH ${src},
inserted AS (
  INSERT INTO publication_drafts (
    draft_id,
    avatar,
    scene,
    asset_type,
    platform,
    asset_id,
    generated_asset_id,
    image_url,
    bucket,
    object_path,
    caption,
    hashtags,
    status,
    metadata,
    created_at,
    updated_at
  )
  SELECT
    ${sql(draftId)}::uuid,
    avatar,
    scene,
    asset_type,
    ${sql(platform)},
    asset_id::uuid,
    generated_asset_id,
    ${sql(baseUrl)} || '/' || bucket || '/' || object_path,
    bucket,
    object_path,
    ${sql(caption)},
    ${sqlJson(hashtags)},
    'draft',
    jsonb_build_object(
      'source', 'create-publication-draft',
      'request', ${sqlJson(body)},
      'generatedAssetId', generated_asset_id,
      'assetId', asset_id,
      'mimeType', mime_type,
      'registryMetadata', metadata
    ),
    now(),
    now()
  FROM chosen
  RETURNING
    draft_id,
    avatar,
    scene,
    asset_type,
    platform,
    asset_id,
    generated_asset_id,
    image_url,
    bucket,
    object_path,
    caption,
    hashtags,
    status,
    metadata,
    approved_at,
    published_at,
    created_at,
    updated_at
)
SELECT * FROM inserted;
`;

return {
  json: {
    ok: true,
    skipQuery: false,
    query
  }
};
